VOICE_VALID = {"NEUTRAL", "POSITIVE", "NEGATIVE"}


def aggregate_call_emotion(
        labels: List[str],
        weights: Optional[Dict[str, float]] = None,
        min_votes: int = 1,
):
    """
    输入：多段标签列表
    输出：通话级最终标签 + 置信度
    """
    labels = [x for x in labels if x in VOICE_VALID]
    if len(labels) < min_votes:
        return None, 0.0

    cnt = Counter(labels)
    total = sum(cnt.values())

    # 负面优先（可选）
    neg_ratio = cnt.get("NEGATIVE", 0) / total
    if neg_ratio >= 0.2:
        conf = min(0.70 + 0.30 * neg_ratio, 0.95)
        return "NEGATIVE", conf

    if weights is None:
        weights = {"NEGATIVE": 1.5, "POSITIVE": 1.2, "NEUTRAL": 1.0}

    scores = {k: cnt.get(k, 0) * weights.get(k, 1.0) for k in VOICE_VALID}
    best = max(scores, key=scores.get)

    # 简单 conf：领先占比
    sorted_scores = sorted(scores.values(), reverse=True)
    gap = sorted_scores[0] - sorted_scores[1] if len(sorted_scores) >= 2 else sorted_scores[0]
    conf = min(0.60 + 0.10 * gap, 0.90)

    return best, conf


def extract_voice_urls(data) -> List[str]:
    """
    递归提取 JSON 内所有 'voice' 字段里的 URL
    忽略 download_voice
    """
    voice_urls = []

    for record in data['data']['records']:
        # 检查 notify 字段是否为 "asrmessage_notify"
        if record.get('notify') == "asrmessage_notify":
            # 提取 record.voice（字符串）
            voice = record.get('voice')
            if voice:  # 确保 voice 字段存在且不为空
                voice_urls.append(voice)

    return voice_urls

def transcribe_audio_stream(session_id: str, audio_stream, filename: str, content_type: str) -> Dict:
    """
    把“文件流”直接以 multipart/form-data 发送给转录服务
    """
    start = time.time()

    files = {
        # (filename, fileobj, content_type)
        "audio": (filename, audio_stream, content_type or "application/octet-stream")
    }
    data = {"session_id": session_id, "format": "mp3"}

    resp = requests.post(
        "http://10.70.190.54:8080/transcribe",
        files=files,
        data=data,
        timeout=120,   # 下游转录超时
    )
    resp.raise_for_status()
    result = resp.json()

    elapsed = time.time() - start
    print(
        f"会话 {session_id} 完成，耗时: {elapsed:.2f}秒, "
        f"使用连接: {result.get('connection_id')}, "
        f"结果: {result.get('text', '')[:50]}"
    )
    return result


def process_one(self, url: str, session_id: str) -> Dict:
    try:
        # 1. 下载 wav 到内存
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()

        content_type = resp.headers.get("Content-Type", "audio/wav")
        wav_bytes = resp.content

        # 2. 构造内存文件对象
        audio_buffer = io.BytesIO(wav_bytes)
        audio_buffer.name = f"{session_id}.wav"  # 非必须，但强烈建议

        # 3. 调用原有转写逻辑
        return self.transcribe_audio_stream(
            session_id=session_id,
            audio_stream=audio_buffer,
            filename=audio_buffer.name,
            content_type=content_type,
        )

    except Exception as e:
        return {
            "session_id": session_id,
            "url": url,
            "error": str(e),
        }

import os
from typing import Dict

def process_one_test(file_path: str, session_id: str) -> Dict:
    """
    单条链路：本地 .wav 文件 -> 模拟为音频流 -> 调用 transcribe_audio_stream
    """
    """
        从本地 .mp3 文件读取音频流，传给 transcribe_audio_stream
        """
    try:
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        content_type = "audio/mpeg"  # MP3 的标准 MIME 类型
        filename = f"{session_id}.mp3"  # 保持扩展名为 .mp3，便于服务端识别
        print(filename)

        with open(file_path, "rb") as audio_stream:
            return transcribe_audio_stream(session_id, audio_stream, filename, content_type)

    except Exception as e:
        return {
            "session_id": session_id,
            "file_path": file_path,
            "error": str(e)
        }


